	受控详情加载失败: 'The simulated service could not load the details.',
	服务拒绝读取详情: 'The service denied access to details.'
} as const;
type TextKey = keyof typeof english;
export type CrudText = (key: TextKey) => string;

export function useCrudLocale() {
	const i18n = useAsamProI18n();
	const text: CrudText = (key) => (i18n.locale.value === 'en' ? english[key] : key);
	return { i18n, text };
}

export function crudSchema(text: CrudText) {
	const field = (
		key: string,
		label: TextKey,
		kind: 'text' | 'textarea' = 'text'
	): AsamFieldDefinition => ({
		key,
		kind,
		get label() {
			return text(label);
		}
	});
	const column = (
		key: keyof Row,
		label: TextKey,
		width: number,
		options?: { required?: boolean; sortable?: boolean }
	): AsamOperationColumn<Row> => ({
		key,
		width,
		...options,
		get label() {
			return text(label);
		}
	});
	const fields = [
		{
			key: 'name',
			kind: 'text' as const,
			get label() {
				return text('名称');
			},
			modes: { edit: { rules: [{ required: true, message: () => text('请输入名称') }] } }
		},
		field('team', '团队'),
		field('status', '状态'),
		field('owner', '负责人'),
		field('email', '联系邮箱'),
		field('note', '备注', 'textarea')
	];
	return {
		queryFields: [
			field('name', '名称筛选'),
			field('team', '团队筛选'),
			field('status', '状态筛选'),
			field('owner', '负责人筛选')
		],
		editFields: fields,
		detailFields: fields,
		columns: [
			column('id', '标识', 100, { required: true }),
			column('name', '资产名称', 180, { sortable: true }),
			column('team', '团队', 140),
			column('status', '状态', 140),
			column('owner', '负责人', 150)
		]
	};
}

export function crudConfirmation(text: CrudText, locale: () => string) {
	const confirm = (message: string) =>
		AsamMessageBox.confirm(message, text('请确认'), {
			confirmButtonText: text('确认'),
			cancelButtonText: text('取消')
		}).then(
			() => true,
			() => false
		);
	return {
		confirmDiscard: () => confirm(text('当前修改尚未保存，是否放弃？')),
		confirmRemove: (snapshot: {
			targets: readonly { key: string | number }[];
			rejected: readonly unknown[];
		}) => {
			const english = locale() === 'en';
			const count = snapshot.targets.length;
			const keys = snapshot.targets
				.map(({ key }) => `${typeof key}:${key}`)
				.join(english ? ', ' : '、');
			const rejected = snapshot.rejected.length;
			return confirm(
				english
					? `Delete ${count} selected records (${keys})? Skipped: ${rejected}.`
					: `将删除${count}项：${keys}。拒绝${rejected}项。`
			);
		}
	};
}

import { reactive } from 'vue';
import type { AsamCrudServices, AsamCrudKey, AsamCrudCodec } from '@asam-ui/pro/templates/crud';
import type { AsamFieldModel } from '@asam-ui/pro/components';
import type { AsamRequestContext } from '@asam-ui/ui';
import type { CrudText } from './I18n.js';

export interface Query {
	name: string;
	team: string;
	status: string;
	owner: string;
}
export interface Edit {
	name: string;
	team: string;
	status: string;
	owner: string;
	email: string;
	note: string;
}
export interface Row extends Edit {
	id: AsamCrudKey;
	version: number;
}
export type Failure =
	'success' | 'failure' | 'field-error' | 'unknown-applied' | 'unknown-not-applied';
const strings = <K extends string>(
	model: Readonly<AsamFieldModel>,
	keys: readonly K[]
): Record<K, string> => {
	const result = {} as Record<K, string>;
	for (const key of keys) {
		if (typeof model[key] !== 'string') throw new TypeError(`字段${key}必须为string`);
		result[key] = model[key];
	}
	return result;
};
export const queryCodec: AsamCrudCodec<Query> = {
	encode: (model) => ({ ...model }),
	decode: (model) =>
		strings({ name: '', team: '', status: '', owner: '', ...model }, [
			'name',
			'team',
			'status',
			'owner'
		])
};
export const editCodec: AsamCrudCodec<Edit> = {
	encode: (model) => ({ ...model }),
	decode: (model) => strings(model, ['name', 'team', 'status', 'owner', 'email', 'note'])
};
export const initialQuery: Query = { name: '', team: '', status: '', owner: '' };
export const isKey = (value: unknown): value is AsamCrudKey =>
	typeof value === 'string' || (typeof value === 'number' && Number.isFinite(value));

/** 合成服务可整体替换；延迟是真实await，统计记录实际服务入口与scope。 */
export function createDemoService(text: CrudText = (value) => value) {
	const controls = reactive({
		delay: 100,
		listError: false,
		loadError: false,
		missing: false,
		forbidden: false,
		save: 'success' as Failure,
		remove: 'success' as Failure,
		partial: false,
		verifyUnknown: false,
		refreshError: false,
		prefix: '资产'
	});
	const metrics = reactive({
		list: 0,
		load: 0,
		defaults: 0,
		create: 0,
		update: 0,
		remove: 0,
		verify: 0,
		verifyRemove: 0,
		events: [] as {
			name: string;
			scope: string;
			operationId?: string;
			key?: AsamCrudKey;
			start: number;
			end: number;
		}[]
	});
	const stores = new Map<string, Map<AsamCrudKey, Row>>();
	const writes = new Map<string, boolean>();
	const deletions = new Map<string, boolean>();
	let sequence = 100;
	function store(scope: string) {
		if (!stores.has(scope))
			stores.set(
				scope,
				new Map(
					Array.from({ length: 100 }, (_, i) => {
						const id = i === 1 ? '0' : i;
						return [
							id,
							{
								id,
								version: 1,
								name: `资产${i}`,
								team: i % 2 ? '研发' : '运营',
								status: '启用',
								owner: `成员${i % 5}`,
								email: `member${i}@example.test`,
								note: `合成记录${i} / ${scope}`
							}
						];
					})
				)
			);
		return stores.get(scope)!;
	}
	async function wait(name: string, scope: string, operationId?: string, key?: AsamCrudKey) {
		const event = { name, scope, operationId, key, start: performance.now(), end: 0 };
		await new Promise((resolve) => setTimeout(resolve, controls.delay));
		event.end = performance.now();
		metrics.events.push(event);
	}
	const identity = (scope: string, id: string, key?: AsamCrudKey) =>
		JSON.stringify([scope, id, typeof key, key]);
	async function save(
		model: Readonly<Edit>,
		scope: string,
		operationId: string,
		id?: AsamCrudKey
	) {
		const failure = controls.save;
		await wait(id === undefined ? 'create' : 'update', scope, operationId, id);
		if (failure === 'field-error')
			return {
				status: 'failure' as const,
				message: text('服务字段校验失败'),
				issues: [{ key: 'name', message: text('名称已被占用，请修改名称') }]
			};
		if (failure === 'failure')
			return { status: 'failure' as const, message: text('服务明确拒绝，未写入') };
		const applied = failure !== 'unknown-not-applied';
		if (applied) {
			const key = id ?? ++sequence;
			store(scope).set(key, {
				...model,
				id: key,
				version: (store(scope).get(key)?.version ?? 0) + 1
			});
		}
		writes.set(identity(scope, operationId), applied);
		if (controls.refreshError) controls.listError = true;
		return failure.startsWith('unknown')
			? { status: 'unknown' as const, message: text('响应丢失，请核实服务器结果') }
			: { status: 'success' as const, data: { id } };
	}
	const services: AsamCrudServices<Row, Query, Edit, AsamCrudKey> = {
		async list(request, context) {
			metrics.list++;
			const snapshot = [...store(context.scope).values()].map((row) => ({ ...row }));
			await wait('list', context.scope);
			if (controls.listError) throw new Error(text('受控列表失败'));
			const rows = snapshot.filter((row) =>
				Object.entries(request.query).every(
					([key, value]) => !value || String(Reflect.get(row, key)).includes(value)
				)
			);
			if (request.sort) {
				const { field, order } = request.sort;
				rows.sort(
					(a, b) =>
						String(Reflect.get(a, field)).localeCompare(
							String(Reflect.get(b, field)),
							'zh-CN',
							{ numeric: true }
						) * (order === 'ascending' ? 1 : -1)
				);
			}
			return {
				list: rows
					.slice(
						(request.currentPage - 1) * request.pageSize,
						request.currentPage * request.pageSize
					)
					.map((row) => ({ ...row, name: row.name.replace('资产', controls.prefix) })),
				total: rows.length
			};
		},
		async defaults(context) {
			metrics.defaults++;
			await wait('defaults', context.scope);
			return { name: '', team: '研发', status: '启用', owner: '成员0', email: '', note: '' };
		},
		async load(key, context) {
			metrics.load++;
			await wait('load', context.scope, undefined, key);
			if (controls.loadError) throw new Error(text('受控编辑加载失败'));
			const row = store(context.scope).get(key);
			if (!row) throw new Error(text('记录已不存在'));
			return { ...row };
		},
		create(model, operation, context) {
			metrics.create++;
			return save(model, context.scope, operation.target.operationId);
		},
		update(key, model, operation, context) {
			metrics.update++;
			return save(model, context.scope, operation.target.operationId, key);
		},
		async verify(operation, context) {
			metrics.verify++;
			await wait('verify', operation.scope, operation.target.operationId);
			if (controls.verifyUnknown) return { status: 'unknown' };
			return writes.get(identity(operation.scope, operation.target.operationId))
				? { status: 'success', data: { verified: true } }
				: { status: 'not-applied' };
		},
		async resolve(keys, context) {
			return keys.map((key) => {
				const row = store(context.scope).get(key);
				return row
					? {
							key,
							target: {
								key,
								version: String(row.version),
								payload: { name: row.name }
							}
						}
					: { key, reason: text('记录不存在') };
			});
		},
		async remove(target, snapshot) {
			metrics.remove++;
			const failure = controls.partial && target.key === '0' ? 'failure' : controls.remove;
			await wait('remove', snapshot.context.scope, snapshot.operationId, target.key);
			if (failure === 'failure' || failure === 'field-error')
				return { key: target.key, status: 'failure', message: text('明确未应用，可重试') };
			const applied = failure !== 'unknown-not-applied';
			if (applied) store(snapshot.context.scope).delete(target.key);
			deletions.set(
				identity(snapshot.context.scope, snapshot.operationId, target.key),
				applied
			);
			if (controls.refreshError) controls.listError = true;
			return {
				key: target.key,
				status: failure.startsWith('unknown') ? 'unknown' : 'success'
			};
		},
		async verifyRemove(target, snapshot) {
			metrics.verifyRemove++;
			await wait('verifyRemove', snapshot.context.scope, snapshot.operationId, target.key);
			return {
				key: target.key,
				status: controls.verifyUnknown
					? 'unknown'
					: deletions.get(
								identity(snapshot.context.scope, snapshot.operationId, target.key)
						  )
						? 'success'
						: 'unsent'
			};
		}
	};
	async function detail(key: string | number, context: AsamRequestContext) {
		metrics.load++;
		await wait('detail', context.scope, undefined, key);
		if (controls.loadError) throw new Error(text('受控详情加载失败'));
		if (controls.forbidden)
			return { status: 'forbidden' as const, message: text('服务拒绝读取详情') };
		const row = store(context.scope).get(key);
		return controls.missing || !row
			? { status: 'missing' as const }
			: { status: 'ready' as const, data: { ...row } };
	}
	return { services, detail, controls, metrics };
}
